css:
.ss { direction: rtl; text-align: right; font-family: "Tajawal", "Cairo", "Arial", sans-serif; font-size: 11px; color: #000; }
.ss table { width: 100%; border-collapse: collapse; }
.ss-head td { border: none; vertical-align: middle; padding: 4px; }
.ss-logo { width: 35%; height: 55px; }
.ss-title-cell { width: 65%; text-align: center; }
.ss-title { font-weight: bold; font-size: 14px; }
.ss-branch { font-weight: bold; font-size: 13px; margin-top: 4px; }
.ss-table { margin-top: 10px; border: 1px solid #000; }
.ss-table thead { display: table-header-group; }
.ss-table tr { page-break-inside: avoid; }
.ss-table th { background: #1f2621 !important; color: #fff !important; font-weight: bold; text-align: center; padding: 8px 4px; border: 1px solid #1f2621; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.ss-table td { border: 1px solid #000; padding: 3px 5px; }
.ss-table tfoot th { background: #eeeeee !important; color: #000 !important; border: 1px solid #000; }
.ss-table .c { text-align: center; }
.ss-table .b { font-weight: bold; }
.ss-table .s { text-align: right; font-weight: bold; }
.ss-table .n { text-align: left; direction: ltr; }
